// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// RecordAuditEvent Record an entry (services only)
	// (POST /v1/audit/events)
	RecordAuditEvent(ctx context.Context, request RecordAuditEventRequestObject) (RecordAuditEventResponseObject, error)
	// ExpireAuditEvents Delete an org's entries older than an instant, for its audit retention (the organization service only)
	// (POST /v1/internal/organizations/{org_id}/audit/expire)
	ExpireAuditEvents(ctx context.Context, request ExpireAuditEventsRequestObject) (ExpireAuditEventsResponseObject, error)
	// PurgeOrgData Delete everything this service keeps for an org, and count what is left (the organization service only)
	// (DELETE /v1/internal/organizations/{org_id}/data)
	PurgeOrgData(ctx context.Context, request PurgeOrgDataRequestObject) (PurgeOrgDataResponseObject, error)
	// ExportOrgData Everything this service keeps for an org, for its export (the organization service only)
	// (GET /v1/internal/organizations/{org_id}/data)
	ExportOrgData(ctx context.Context, request ExportOrgDataRequestObject) (ExportOrgDataResponseObject, error)
	// ExportUserData What this service keeps about one person, for their own export (the organization service only)
	// (GET /v1/internal/users/{user_id}/data)
	ExportUserData(ctx context.Context, request ExportUserDataRequestObject) (ExportUserDataResponseObject, error)
	// ListAuditEvents An org's entries, newest first
	// (GET /v1/organizations/{org_id}/audit-events)
	ListAuditEvents(ctx context.Context, request ListAuditEventsRequestObject) (ListAuditEventsResponseObject, error)
	// ExportAuditEvents An org's entries as CSV, oldest first, for a compliance request
	// (GET /v1/organizations/{org_id}/audit-events/export)
	ExportAuditEvents(ctx context.Context, request ExportAuditEventsRequestObject) (ExportAuditEventsResponseObject, error)
}

